parts.openscad_module:
$fn = 96;

// ── Parameters ───────────────────────────────────────────
lm_od        = 15;    // LM8UU outer diameter
lm_length    = 24;    // LM8UU length
rod_spacing  = 40;    // rod centre-to-centre (Y)
end_wall     = 6;     // wall beyond bearing ends (X)
side_wall    = 5;     // wall beside bearing (Y)
top_wall     = 4;     // wall above bearing
bottom_wall  = 4;     // minimum wall below bearing — MUST be ≥ wall_thickness
relief_depth = 8;     // depth of bottom material relief
mount_hole_d = 4.5;   // M4 clearance hole

// Hex nut trap — M3 (must match bolt family)
hex_nut_af   = 5.5;   // M3 across-flats
hex_nut_h    = 2.6;   // M3 nut height
hex_bolt_d   = 3.4;   // M3 clearance (3.0 + 0.4)

car_l = lm_length + 2*end_wall;
car_w = rod_spacing + lm_od + 2*side_wall;
car_h = lm_od + top_wall + bottom_wall;

rod_z = -car_h/2 + bottom_wall + lm_od/2;  // rod bore centre Z

module dual_rod_carriage() {
  difference() {
    cube([car_l, car_w, car_h], center = true);

    // Rod bores — along X
    for (y = [-rod_spacing/2, rod_spacing/2])
      translate([0, y, rod_z])
        rotate([0, 90, 0])
          cylinder(h = car_l + 2, d = lm_od + 0.1, center = true, $fn = 64);

    // Bottom relief — bottom_wall stays solid
    // CORRECT formula: -car_h/2 + bottom_wall + relief_depth/2
    // WRONG formula:   -car_h/2 + wall_thickness/2  (removes bottom wall)
    translate([0, 0, -car_h/2 + bottom_wall + relief_depth/2])
      cube([car_l - 2*end_wall, car_w - 2*side_wall, relief_depth], center = true);

    // Mounting holes — centered at z=0 for full through-height
    for (x = [-car_l/4, car_l/4])
      for (y = [-car_w/4, car_w/4])
        translate([x, y, 0])
          cylinder(h = car_h + 2, d = mount_hole_d, center = true, $fn = 32);

    // Hex nut pocket — M3 (hex_nut_af=5.5 matches hex_bolt_d=3.4)
    translate([0, 0, car_h/2 - hex_nut_h/2])
      cylinder(h = hex_nut_h + 0.2, d = hex_nut_af / cos(30) + 0.2,
               center = true, $fn = 6);

    // Coaxial bolt clearance — same bolt family as hex nut
    cylinder(h = car_h + 2, d = hex_bolt_d, center = true, $fn = 32);
  }
}

dual_rod_carriage();
